--
-- Struktur dari tabel `ref_gaji_pokok`
--

CREATE TABLE `ref_gaji_pokok` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `jenis_pegawai` enum('PNS','PPPK') NOT NULL COMMENT 'Pembeda tabel 1 (PPPK) dan tabel 2 (PNS)',
  `golongan` varchar(10) NOT NULL COMMENT 'Format: III/a, IV/b (PNS) ATAU IX, XVII (PPPK)',
  `mkg` int(10) UNSIGNED NOT NULL COMMENT 'Masa Kerja Golongan (0 sampai 32)',
  `nominal_gaji` decimal(15,2) NOT NULL COMMENT 'Nominal gaji dalam Rupiah',
  `tahun_berlaku` year(4) NOT NULL DEFAULT 2024 COMMENT 'Tahun dasar aturan',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

