--
-- Struktur dari tabel `riwayat_gaji`
--

CREATE TABLE `riwayat_gaji` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `pegawai_id` bigint(20) UNSIGNED NOT NULL,
  `gaji_pokok` decimal(15,2) NOT NULL,
  `tmt_berlaku` date NOT NULL,
  `jenis` enum('PANGKAT','KGB','PP','LAINNYA') NOT NULL DEFAULT 'KGB',
  `nomor_sk` varchar(50) NOT NULL,
  `tanggal_sk` date NOT NULL,
  `pejabat_penetap` varchar(100) NOT NULL,
  `dasar_peraturan` varchar(50) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

